<?php declare(strict_types=1);namespace App\Interface\Http\Arena;use App\Application\Arena\Mapper\ArenaRoomSummaryMapper;use App\Application\Arena\Mapper\DuelResponseMapper;use App\Application\Arena\Service\DuelLifecycleService;use App\Application\Arena\Service\GetDuelService;use App\Application\Arena\Service\ListArenaRoomsService;use App\Application\Arena\Service\ListArenaSubjectsService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineDuelQuestionSelector;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineDuelRepository;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Infrastructure\Persistence\Doctrine\Taxonomy\DoctrineTaxonomySubjectRepository;use App\Interface\Http\Arena\Controller\ArenaController;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;final class ArenaRouteRegistrar { public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){} public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$repo=new DoctrineDuelRepository($em);$mapper=new DuelResponseMapper();$c=new ArenaController($this->auth,new DuelLifecycleService($repo,new DoctrineDuelQuestionSelector($em),new DoctrineTransactionManager($em)),new GetDuelService($repo,$mapper),new ListArenaRoomsService($repo,new ArenaRoomSummaryMapper()),new ListArenaSubjectsService(new DoctrineTaxonomySubjectRepository($em)),$mapper,$this->responses);$f=new ArenaRequestFactory();$page=static function(ServerRequestInterface $r):array{$q=$r->getQueryParams();return [max(1,(int)($q["page"]??1)),min(100,max(1,(int)($q["per_page"]??25)))];};$app->post("/v1/arena/duels",fn(ServerRequestInterface $r,ResponseInterface $s):ResponseInterface=>$c->create($r,$s,$f->create($r)));$app->post("/v1/arena/duels/join",fn(ServerRequestInterface $r,ResponseInterface $s):ResponseInterface=>$c->join($r,$s,$f->code($r)));$app->post("/v1/arena/duels/{id}/join",fn(ServerRequestInterface $r,ResponseInterface $s,array $a):ResponseInterface=>$c->joinPublic($r,$s,(string)$a["id"]));$app->get("/v1/arena/duels/public",function(ServerRequestInterface $r,ResponseInterface $s)use($c,$page):ResponseInterface{[$p,$n]=$page($r);return$c->publicRooms($r,$s,$p,$n);});$app->get("/v1/arena/duels/mine/private",function(ServerRequestInterface $r,ResponseInterface $s)use($c,$page):ResponseInterface{[$p,$n]=$page($r);return$c->privateRooms($r,$s,$p,$n);});$app->get("/v1/arena/subjects",function(ServerRequestInterface $r,ResponseInterface $s)use($c,$page):ResponseInterface{[$p,$n]=$page($r);return$c->listSubjects($r,$s,$p,$n);});$app->get("/v1/arena/duels/{id}",fn(ServerRequestInterface $r,ResponseInterface $s,array $a):ResponseInterface=>$c->get($r,$s,(string)$a["id"]));$app->put("/v1/arena/duels/{id}/subjects",fn(ServerRequestInterface $r,ResponseInterface $s,array $a):ResponseInterface=>$c->subjects($r,$s,(string)$a["id"],$f->subjects($r)));$app->delete("/v1/arena/duels/{id}",fn(ServerRequestInterface $r,ResponseInterface $s,array $a):ResponseInterface=>$c->remove($r,$s,(string)$a["id"]));$app->post("/v1/arena/duels/{id}/start",fn(ServerRequestInterface $r,ResponseInterface $s,array $a):ResponseInterface=>$c->start($r,$s,(string)$a["id"]));} }
